package com.fitlife.mfe.personal.bff.service;import com.fasterxml.jackson.databind.JsonNode;import com.fitlife.mfe.personal.bff.client.ApiGatewayClient;import java.util.Map;import org.springframework.http.HttpMethod;import org.springframework.stereotype.Service;
@Service public class PersonaisBffService{private final ApiGatewayClient g;public PersonaisBffService(ApiGatewayClient g){this.g=g;}public JsonNode usuario(String id,String t){return g.exchange("/api/usuarios/"+id,HttpMethod.GET,null,t);}public JsonNode listar(String t){return g.exchange("/api/personais",HttpMethod.GET,null,t);}public JsonNode contatar(String personal,String user,String t){return g.exchange("/api/personais/"+personal+"/contatos",HttpMethod.POST,Map.of("usuarioId",user),t);}}
